insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para o cumprimento de mandado expedido pela autoridade judiciária, a autoridade policial poderá expedir tantos outros quantos necessários às diligências, devendo neles ser fielmente reproduzido o teor do mandado original.', '["Autoridade policial expede mandados auxiliares para cumprir o do juiz.","Reproduz fielmente o teor do mandado original."]'::jsonb, '["Mandados auxiliares reproduzem o original."]'::jsonb, 'O delegado expede cópias do mandado para diferentes equipes cumprirem a ordem.', '["Assertiva que autoriza a autoridade policial a alterar o conteúdo do mandado ao reproduzi-lo erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
