insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A captura poderá ser requisitada, à vista de mandado judicial, por qualquer meio de comunicação, tomadas pela autoridade a quem se fizer a requisição as precauções necessárias para averiguar a autenticidade desta.', '["Captura pode ser requisitada por qualquer meio de comunicação.","Exige mandado judicial.","A autoridade requisitada verifica a autenticidade."]'::jsonb, '["Autenticidade verificada."]'::jsonb, 'A prisão é requisitada por meio eletrônico, e a autoridade confirma a autenticidade.', '["Assertiva que dispensa a verificação de autenticidade da requisição de captura erra."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
