insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As pessoas presas provisoriamente ficarão separadas das que já estiverem definitivamente condenadas, nos termos da lei de execução penal. O militar preso em flagrante delito, após a lavratura dos procedimentos legais, será recolhido a quartel da instituição a que pertencer, onde ficará preso à disposição das autoridades competentes.', '["Presos provisórios separados dos condenados definitivos.","Militar preso em flagrante: recolhido a quartel da própria instituição."]'::jsonb, '["Separação entre provisórios e definitivos."]'::jsonb, 'Preso preventivo e condenado definitivo ficam em alas diferentes.', '["Assertiva que permite manter juntos presos provisórios e condenados definitivos erra."]'::jsonb, '[]'::jsonb, '["Art. 295"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-300'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O investigado por crimes contra a dignidade sexual, quando preso cautelarmente, e o condenado pelos mesmos crimes deverão ser submetidos obrigatoriamente à identificação do perfil genético, mediante extração de DNA, por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional.', '["Investigado preso cautelarmente por crime contra a dignidade sexual e condenado pelos mesmos crimes.","Identificação obrigatória do perfil genético (DNA).","Técnica adequada e indolor, no ingresso no estabelecimento prisional."]'::jsonb, '["Incluído pela Lei nº 15.280, de 2025."]'::jsonb, 'Ao ingressar no presídio, o preso por estupro tem o DNA coletado.', '["Assertiva que torna facultativa a coleta de DNA do art. 300-A erra: é obrigatória."]'::jsonb, '[]'::jsonb, '["Art. 9º-A da Lei de Execução Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-300-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer do povo poderá e as autoridades policiais e seus agentes deverão prender quem quer que seja encontrado em flagrante delito.', '["Qualquer pessoa PODE prender quem esteja em flagrante (flagrante facultativo).","Autoridades policiais e seus agentes DEVEM prender (flagrante obrigatório)."]'::jsonb, '["Flagrante facultativo para o povo; obrigatório para a polícia."]'::jsonb, 'Um cidadão detém o autor de um furto em andamento (flagrante facultativo).', '["Assertiva que torna obrigatória a prisão em flagrante para qualquer cidadão erra."]'::jsonb, '[]'::jsonb, '["Art. 302"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-301'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se em flagrante delito quem está cometendo a infração penal (flagrante próprio); acaba de cometê-la (flagrante próprio); é perseguido, logo após, pela autoridade, pelo ofendido ou por qualquer pessoa, em situação que faça presumir ser autor (flagrante impróprio ou quase flagrante); ou é encontrado, logo depois, com instrumentos, armas, objetos ou papéis que façam presumir ser ele autor da infração (flagrante presumido).', '["I e II: flagrante próprio (está cometendo ou acaba de cometer).","III: flagrante impróprio (perseguição logo após).","IV: flagrante presumido (encontrado logo depois com objetos)."]'::jsonb, '["Perseguição (III) exige continuidade; encontro (IV) exige que seja ''logo depois''."]'::jsonb, 'Quem é encontrado logo depois com a arma do crime está em flagrante presumido.', '["Assertiva que classifica quem é perseguido logo após o crime como flagrante presumido erra: é flagrante impróprio."]'::jsonb, '[{"termo":"Flagrante impróprio","significado":"Perseguição logo após o crime em situação que faz presumir a autoria."}]'::jsonb, '["Art. 301","Art. 303"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-302'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas infrações permanentes, entende-se o agente em flagrante delito enquanto não cessar a permanência.', '["Crime permanente: flagrante enquanto durar a permanência."]'::jsonb, '["Permite o flagrante a qualquer momento da permanência, inclusive com ingresso em domicílio."]'::jsonb, 'Em sequestro em andamento, o agente está em flagrante enquanto a vítima estiver privada de liberdade.', '["Assertiva que limita o flagrante em crime permanente ao momento inicial da conduta erra."]'::jsonb, '[{"termo":"Crime permanente","significado":"Consumação que se prolonga no tempo."}]'::jsonb, '["Art. 302"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-303'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentado o preso à autoridade competente, ouvirá esta o condutor e colherá, desde logo, sua assinatura, entregando a este cópia do termo e recibo de entrega do preso. Em seguida, procederá à oitiva das testemunhas que o acompanharem e ao interrogatório do acusado sobre a imputação, colhendo, após cada oitiva, as respectivas assinaturas, lavrando, afinal, o auto. Resultando das respostas fundada suspeita contra o conduzido, a autoridade mandará recolhê-lo à prisão, exceto no caso de livrar-se solto ou de prestar fiança. A falta de testemunhas da infração não impede o auto, mas, com o condutor, deverão assiná-lo pelo menos duas pessoas que hajam testemunhado a apresentação do preso. Quando o acusado se recusar a assinar, não souber ou não puder fazê-lo, o auto será assinado por duas testemunhas que tenham ouvido sua leitura.', '["Ordem da oitiva: condutor, testemunhas, depois o preso.","Cada oitiva colhe a respectiva assinatura.","§1º: fundada suspeita leva ao recolhimento, salvo se livrar-se solto ou prestar fiança.","§2º: falta de testemunhas da infração não impede o auto; duas pessoas que testemunhem a apresentação assinam.","§3º: recusa ou impossibilidade de assinar do acusado: duas testemunhas da leitura."]'::jsonb, '["Primeiro o condutor, depois as testemunhas, por fim o preso."]'::jsonb, 'O delegado ouve o condutor, as testemunhas e, por fim, o preso, e lavra o auto.', '["Assertiva que determina interrogar o preso antes da oitiva do condutor erra."]'::jsonb, '[{"termo":"Auto de prisão em flagrante","significado":"Peça que documenta a prisão em flagrante."}]'::jsonb, '["Art. 306","Art. 310"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-304'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na falta ou no impedimento do escrivão, qualquer pessoa designada pela autoridade lavrará o auto de prisão em flagrante, depois de prestado o compromisso legal.', '["Falta ou impedimento do escrivão: qualquer pessoa designada pela autoridade lavra o auto.","Exige o compromisso legal."]'::jsonb, '["Compromisso legal prévio do substituto do escrivão."]'::jsonb, 'Sem escrivão na delegacia, outra pessoa designada presta compromisso e lavra o auto.', '["Assertiva que dispensa o compromisso legal da pessoa designada para lavrar o auto erra."]'::jsonb, '[]'::jsonb, '["Art. 304"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-305'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente, ao Ministério Público e à família do preso ou à pessoa por ele indicada. Em até 24 horas após a prisão, será encaminhado ao juiz competente o auto de prisão em flagrante e, caso o autuado não informe o nome de seu advogado, cópia integral para a Defensoria Pública. No mesmo prazo, será entregue ao preso, mediante recibo, a nota de culpa, assinada pela autoridade, com o motivo da prisão, o nome do condutor e os das testemunhas.', '["Comunicação imediata ao juiz, ao MP e à família ou pessoa indicada.","Em até 24 horas: auto ao juiz e, se não houver advogado, cópia à Defensoria Pública.","Mesmo prazo: nota de culpa entregue ao preso, com recibo."]'::jsonb, '["24 horas para o auto e para a nota de culpa.","A nota de culpa traz motivo, condutor e testemunhas."]'::jsonb, 'Em 24 horas da prisão, o preso recebe a nota de culpa e o auto segue ao juiz.', '["Assertiva que fixa em 48 horas o prazo para encaminhar o auto de prisão em flagrante ao juiz erra: são 24 horas."]'::jsonb, '[{"termo":"Nota de culpa","significado":"Documento que informa ao preso o motivo da prisão, o condutor e as testemunhas."}]'::jsonb, '["Art. 304","Art. 310"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-306'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o fato for praticado em presença da autoridade, ou contra esta, no exercício de suas funções, constarão do auto a narração do fato, a voz de prisão, as declarações do preso e os depoimentos das testemunhas, assinados pela autoridade, pelo preso e pelas testemunhas, e remetidos imediatamente ao juiz a quem couber conhecer do fato delituoso.', '["Fato praticado na presença da autoridade ou contra ela, no exercício das funções.","Auto narra o fato, a voz de prisão, declarações do preso e depoimentos.","Assinado por autoridade, preso e testemunhas, e remetido ao juiz."]'::jsonb, '["Procedimento simplificado quando o fato ocorre diante da autoridade."]'::jsonb, 'Desacato praticado diante do juiz: lavra-se o auto e remete-se ao juízo competente.', '["Assertiva que dispensa a remessa imediata do auto ao juiz competente nesses casos erra."]'::jsonb, '[]'::jsonb, '["Art. 304"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-307'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não havendo autoridade no lugar em que se tiver efetuado a prisão, o preso será logo apresentado à do lugar mais próximo.', '["Sem autoridade no local da prisão: apresentação à autoridade do lugar mais próximo."]'::jsonb, '["Apresentação imediata."]'::jsonb, 'Preso em área remota é levado à delegacia do município mais próximo.', '["Assertiva que manda aguardar a instalação de autoridade no local da prisão erra: o preso é apresentado à mais próxima."]'::jsonb, '[]'::jsonb, '["Art. 304"]'::jsonb, 'under_review', 'claude'
