on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos juízos criminais e delegacias de polícia, haverá um livro especial, com termos de abertura e de encerramento, numerado e rubricado em todas as suas folhas pela autoridade, destinado especialmente aos termos de fiança. O termo será lavrado pelo escrivão e assinado pela autoridade e por quem prestar a fiança, e dele extrair-se-á certidão para juntar-se aos autos. O réu e quem prestar a fiança serão notificados pelo escrivão das obrigações e da sanção previstas nos arts. 327 e 328, o que constará dos autos.', '["Livro especial de termos de fiança, numerado e rubricado.","Termo lavrado pelo escrivão e assinado pela autoridade e por quem presta a fiança.","Certidão juntada aos autos.","Notificação das obrigações e sanções dos arts. 327 e 328."]'::jsonb, '["Formalidades do termo de fiança."]'::jsonb, 'O escrivão lavra o termo de fiança no livro especial.', '["Assertiva que dispensa a notificação do réu quanto às obrigações da fiança erra."]'::jsonb, '[]'::jsonb, '["Art. 327","Art. 328"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-329'
