insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A fiança, que será sempre definitiva, consistirá em depósito de dinheiro, pedras, objetos ou metais preciosos, títulos da dívida pública, federal, estadual ou municipal, ou em hipoteca inscrita em primeiro lugar. A avaliação de imóvel, pedras, objetos ou metais preciosos será feita imediatamente por perito nomeado pela autoridade. Quando a fiança consistir em caução de títulos da dívida pública, o valor será determinado pela sua cotação em Bolsa, e, sendo nominativos, exigir-se-á prova de que estão livres de ônus.', '["Fiança sempre definitiva.","Modalidades: depósito de dinheiro, pedras, objetos ou metais preciosos, títulos da dívida pública, ou hipoteca em primeiro lugar.","Avaliação imediata por perito.","Títulos: cotação em Bolsa e prova de que estão livres de ônus."]'::jsonb, '["Fiança sempre DEFINITIVA."]'::jsonb, 'A fiança é prestada mediante depósito em dinheiro.', '["Assertiva que admite fiança provisória no art. 330 erra: ela é sempre definitiva."]'::jsonb, '[]'::jsonb, '["Art. 331"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-330'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O valor em que consistir a fiança será recolhido à repartição arrecadadora federal ou estadual, ou entregue ao depositário público, juntando-se aos autos os respectivos conhecimentos. Nos lugares em que o depósito não se puder fazer de pronto, o valor será entregue ao escrivão ou pessoa abonada, a critério da autoridade, e dentro de três dias dar-se-á ao valor o destino que lhe assina o artigo, o que tudo constará do termo de fiança.', '["Valor recolhido à repartição arrecadadora ou entregue ao depositário público.","Conhecimentos juntados aos autos.","Sem depósito imediato: entrega ao escrivão ou pessoa abonada e destinação em três dias."]'::jsonb, '["Prazo de três dias para a destinação."]'::jsonb, 'Em local sem banco, a fiança é entregue ao escrivão e depositada em três dias.', '["Assertiva que fixa em 10 dias o prazo para dar destino ao valor entregue ao escrivão erra: são três dias."]'::jsonb, '[]'::jsonb, '["Art. 330"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-331'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de prisão em flagrante, será competente para conceder a fiança a autoridade que presidir ao respectivo auto e, em caso de prisão por mandado, o juiz que o houver expedido, ou a autoridade judiciária ou policial a quem tiver sido requisitada a prisão.', '["Flagrante: autoridade que preside o auto.","Prisão por mandado: juiz que o expediu, ou autoridade a quem foi requisitada a prisão."]'::jsonb, '["Competência para conceder a fiança."]'::jsonb, 'Delegado que preside o auto de flagrante pode conceder a fiança, nos limites da lei.', '["Assertiva que atribui ao Ministério Público a concessão da fiança erra."]'::jsonb, '[]'::jsonb, '["Art. 322"]'::jsonb, 'under_review', 'claude'
