insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a fiança for declarada sem efeito ou passar em julgado sentença que houver absolvido o acusado ou declarada extinta a ação penal, o valor que a constituir, atualizado, será restituído sem desconto, salvo o disposto no parágrafo único do art. 336.', '["Fiança sem efeito, absolvição ou extinção da ação: restituição do valor atualizado, sem desconto.","Ressalva do parágrafo único do art. 336."]'::jsonb, '["Valor devolvido atualizado e sem desconto."]'::jsonb, 'Acusado absolvido recebe de volta o valor da fiança, atualizado.', '["Assertiva que autoriza descontar custas do valor devolvido na absolvição erra."]'::jsonb, '[]'::jsonb, '["Art. 336"]'::jsonb, 'under_review', 'claude'
