insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Será exigido o reforço da fiança quando a autoridade tomar, por engano, fiança insuficiente; quando houver depreciação material ou perecimento dos bens hipotecados ou caucionados, ou depreciação dos metais ou pedras preciosas; ou quando for inovada a classificação do delito. A fiança ficará sem efeito e o réu será recolhido à prisão quando, na conformidade deste artigo, não for reforçada.', '["I: fiança insuficiente por engano.","II: depreciação ou perecimento dos bens dados em garantia.","III: nova classificação do delito.","Sem reforço: fiança sem efeito e réu recolhido à prisão."]'::jsonb, '["Falta de reforço leva à prisão."]'::jsonb, 'Os bens caucionados se depreciam, e o juiz exige o reforço da fiança.', '["Assertiva que dispensa o reforço da fiança quando os bens se depreciam erra."]'::jsonb, '[]'::jsonb, '["Art. 341"]'::jsonb, 'under_review', 'claude'
