select u.id, u.content_sha256, 'A citação inicial far-se-á por mandado, quando o réu estiver no território sujeito à jurisdição do juiz que a houver ordenado.', '["Citação por mandado quando o réu está na jurisdição do juiz."]'::jsonb, '["Citação por mandado é a regra dentro da jurisdição."]'::jsonb, 'O oficial de justiça cita o réu na comarca por mandado.', '["Assertiva que usa precatória para réu dentro da jurisdição do juiz erra."]'::jsonb, '[{"termo":"Citação","significado":"Ato que chama o réu a juízo para se defender."}]'::jsonb, '["Art. 353"]'::jsonb, 'under_review', 'claude'
