select u.id, u.content_sha256, 'Se houver urgência, a precatória, que conterá em resumo os requisitos do art. 354, poderá ser expedida por via telegráfica, depois de reconhecida a firma do juiz, o que a estação expedidora mencionará.', '["Urgência: precatória por via telegráfica.","Contém resumo dos requisitos do art. 354.","Firma do juiz reconhecida."]'::jsonb, '["Meio telegráfico; hoje se usam meios eletrônicos."]'::jsonb, 'Texto histórico, adaptado hoje aos meios eletrônicos.', '["Assertiva que dispensa o reconhecimento da firma do juiz na precatória telegráfica erra."]'::jsonb, '[]'::jsonb, '["Art. 354"]'::jsonb, 'under_review', 'claude'
