select u.id, u.content_sha256, 'A citação do militar far-se-á por intermédio do chefe do respectivo serviço.', '["Citação do militar por intermédio do chefe do serviço."]'::jsonb, '["Rito próprio para o militar."]'::jsonb, 'A citação do policial militar é feita por meio do comandante.', '["Assertiva que cita o militar diretamente, sem o chefe do serviço, erra."]'::jsonb, '[]'::jsonb, '["Art. 359"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-358'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

